class Solution {
  public long maxValue(int[] nums) {
    int n = nums.length;
    long base = 0;
    long[] w = new long[n + 1];
    for (int i = 0; i < n; i++) {
      int sign = i % 2 == 0 ? 1 : -1;
      base += (long) sign * nums[i];
      w[i + 1] = w[i] - 2L * sign * nums[i];
    }
    long NEG = Long.MIN_VALUE / 4;
    long[] bestSame = {NEG, NEG}, bestDiff = {NEG, NEG};
    long bestDelta = 0;
    for (int r = 0; r < n; r++) {
      int q = r % 2;
      long cand = NEG;
      if (bestSame[q] > NEG) cand = Math.max(cand, w[r + 1] + bestSame[q]);
      if (bestDiff[1 - q] > NEG) cand = Math.max(cand, w[r + 1] + bestDiff[1 - q]);
      if (cand > NEG) bestDelta = Math.max(bestDelta, cand);
      int sign = r % 2 == 0 ? 1 : -1;
      // r becomes a candidate left end l for later right ends
      int p = r % 2;
      bestSame[p] = Math.max(bestSame[p], -w[r + 1]);
      bestDiff[p] = Math.max(bestDiff[p], -w[r + 1] - 2L * sign * nums[r]);
    }
    return base + bestDelta;
  }
}
